import sys
import xml.etree.ElementTree as ET
import re

def evaluate_formula(formula, field_values):
    def safe_eval(expr):
        try:
            return eval(expr, {'__builtins__': None}, field_values)
        except:
            raise ValueError(f"Invalid formula: {expr}")

    return safe_eval(formula)

def parse_xml(xml_string):
    root = ET.fromstring(xml_string)
    fields = []
    for field in root.findall('field'):
        name = field.get('name')
        formula = field.get('formula')
        fields.append((name, formula))
    return fields

def generate_html_table(fields):
    html = ['<table>']
    html.append('<tr><th>field</th><th>value</th></tr>')
    field_values = {}
    for name, formula in fields:
        value = evaluate_formula(formula, field_values)
        field_values[name] = value
        html.append(f'<tr><td>{name}</td><td>{str(value)}</td></tr>')
    html.append('</table>')
    return '\n'.join(html)

def main():
    if len(sys.argv) != 2:
        print("Usage: python formula_report.py report.xml", file=sys.stderr)
        sys.exit(1)

    with open(sys.argv[1], 'r') as f:
        xml_content = f.read()

    fields = parse_xml(xml_content)
    html_output = generate_html_table(fields)
    print(html_output)

if __name__ == "__main__":
    main()
